import React from 'react';
import { Info, ArrowUpLeft } from 'lucide-react';
import { customServiceNote, contactInfo } from '../../data/agency-info';
import { createWhatsAppLink } from '../../lib/whatsapp';
import { Button } from '../../components/ui/Button';

export const NoteBanner: React.FC = () => {
  const customPackageUrl = createWhatsAppLink(
    contactInfo.defaultWhatsApp,
    'مرحباً NT Media Agency، أود ترتيب باقة مخصصة وتحديد خدمات معينة حسب متطلباتي.'
  );

  return (
    <section id="note" className="py-12 bg-white">
      <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="rounded-2xl border border-neutral-200 bg-neutral-50/70 p-6 sm:p-8 flex flex-col md:flex-row items-center justify-between gap-6">
          
          <div className="flex items-start gap-4">
            <div className="w-10 h-10 rounded-xl bg-neutral-900 text-white flex items-center justify-center shrink-0 mt-1">
              <Info className="w-5 h-5" />
            </div>
            <div>
              <span className="text-xs font-bold uppercase tracking-wider text-neutral-400 block mb-1">
                {customServiceNote.title}
              </span>
              <p className="text-base sm:text-lg font-bold text-neutral-900 leading-snug">
                {customServiceNote.text}
              </p>
            </div>
          </div>

          <a
            href={customPackageUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="w-full md:w-auto shrink-0"
          >
            <Button size="md" className="w-full md:w-auto gap-2">
              <span>{customServiceNote.buttonText}</span>
              <ArrowUpLeft className="w-4 h-4" />
            </Button>
          </a>

        </div>
      </div>
    </section>
  );
};