import React from 'react';
import { Check, ArrowUpLeft, Sparkles, Star } from 'lucide-react';
import { packagesData } from '../../data/packages';
import { contactInfo } from '../../data/agency-info';
import { createWhatsAppLink } from '../../lib/whatsapp';
import { Card } from '../../components/ui/Card';
import { Button } from '../../components/ui/Button';
import { Badge } from '../../components/ui/Badge';

export const PricingSection: React.FC = () => {
  // تقسيم الباقات: أول 3 باقات بجانب بعضها، وباقة النخبة VIP بعرض كامل
  const standardPackages = packagesData.filter((pkg) => !pkg.isCustomQuote);
  const elitePackage = packagesData.find((pkg) => pkg.isCustomQuote);

  return (
    <section id="packages" className="py-20 lg:py-28 bg-neutral-50/60 border-b border-neutral-200/70">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* رأس القسم */}
        <div className="text-center max-w-2xl mx-auto mb-16 space-y-3">
          <Badge variant="default" className="text-neutral-700">
            خطط الاستثمار الرقمي
          </Badge>
          <h2 className="text-3xl sm:text-4xl font-extrabold text-neutral-900 tracking-tight">
            اختر الباقة المناسبة لمرحلة نموك
          </h2>
          <p className="text-neutral-600 text-sm sm:text-base leading-relaxed">
            باقات تسويقية مدروسة مصممة لتلبية متطلبات الحضور الرقمي وتحقيق أعلى عائد استثماري.
          </p>
        </div>

        {/* شبكة الباقات الأساسية الثلاث الأولى */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-stretch mb-12">
          {standardPackages.map((pkg) => {
            const isPopular = pkg.isPopular;
            const whatsappUrl = createWhatsAppLink(
              contactInfo.defaultWhatsApp,
              `مرحباً NT Media Agency، أرغب بالاشتراك في باقة "${pkg.name} | ${pkg.enName}".`
            );

            return (
              <Card
                key={pkg.id}
                highlighted={isPopular}
                className={`flex flex-col justify-between p-8 relative ${
                  isPopular ? 'bg-white shadow-xl border-neutral-900 lg:-translate-y-2' : 'bg-white'
                }`}
              >
                {/* وسم الأكثر طلباً لباقة التأثير */}
                {isPopular && (
                  <div className="absolute -top-3.5 left-1/2 -translate-x-1/2">
                    <Badge variant="accent" className="flex items-center gap-1.5 px-3 py-1 shadow-sm">
                      <Star className="w-3.5 h-3.5 fill-current text-white" />
                      <span>الأكثر طلباً</span>
                    </Badge>
                  </div>
                )}

                <div>
                  {/* رأس الكرت */}
                  <div className="border-b border-neutral-100 pb-6 mb-6">
                    <div className="flex items-center justify-between mb-1">
                      <h3 className="text-xl font-bold text-neutral-900">{pkg.name}</h3>
                      <span className="text-xs font-mono font-semibold uppercase tracking-wider text-neutral-400">
                        {pkg.enName}
                      </span>
                    </div>
                    <p className="text-xs text-neutral-500 min-h-[32px]">{pkg.description}</p>
                    
                    {/* السعر */}
                    <div className="mt-5 flex items-baseline gap-1.5">
                      <span className="text-4xl font-extrabold text-neutral-900 font-mono tracking-tight">
                        {pkg.price}
                      </span>
                      <span className="text-xs font-medium text-neutral-500">ر.س / شهرياً</span>
                    </div>
                  </div>

                  {/* قائمة الميزات والنقاط */}
                  <ul className="space-y-3 mb-8">
                    {pkg.features.map((feature, idx) => (
                      <li key={idx} className="flex items-start gap-3 text-sm text-neutral-700">
                        <div className="w-5 h-5 rounded-full bg-neutral-100 flex items-center justify-center shrink-0 mt-0.5">
                          <Check className="w-3.5 h-3.5 text-neutral-900" />
                        </div>
                        <span className="leading-snug">{feature}</span>
                      </li>
                    ))}
                  </ul>
                </div>

                {/* زر الإجراء داخل الكرت */}
                <a
                  href={whatsappUrl}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="w-full"
                >
                  <Button
                    fullWidth
                    variant={isPopular ? 'primary' : 'outline'}
                    size="md"
                    className="gap-2"
                  >
                    <span>{pkg.ctaText}</span>
                    <ArrowUpLeft className="w-4 h-4" />
                  </Button>
                </a>
              </Card>
            );
          })}
        </div>

        {/* كرت باقة النخبة VIP بعرض كامل */}
        {elitePackage && (
          <div className="mt-8">
            <Card className="p-8 sm:p-10 bg-neutral-900 text-white border-neutral-800 shadow-xl overflow-hidden relative">
              <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-center">
                
                {/* تفاصيل الباقة والعنوان */}
                <div className="lg:col-span-5 space-y-4">
                  <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-white/10 text-xs font-semibold text-white tracking-wide border border-white/10">
                    <Sparkles className="w-3.5 h-3.5 text-amber-300" />
                    <span>باقة VIP الخاصة</span>
                  </div>

                  <h3 className="text-2xl sm:text-3xl font-extrabold tracking-tight">
                    {elitePackage.name} <span className="text-neutral-400 font-light">({elitePackage.enName})</span>
                  </h3>

                  <p className="text-sm text-neutral-300 leading-relaxed">
                    {elitePackage.description}
                  </p>

                  <div className="pt-2">
                    <span className="text-xs uppercase tracking-widest text-neutral-400 block mb-1">الاستثمار</span>
                    <span className="text-xl font-bold text-white">
                      {elitePackage.price}
                    </span>
                  </div>

                  <div className="pt-4">
                    <a
                      href={createWhatsAppLink(
                        contactInfo.defaultWhatsApp,
                        'مرحباً NT Media Agency، نود الاستفسار وحجز استشارة بخصوص باقة النخبة VIP.'
                      )}
                      target="_blank"
                      rel="noopener noreferrer"
                    >
                      <Button
                        variant="secondary"
                        size="lg"
                        className="bg-white text-neutral-900 hover:bg-neutral-100 gap-2 w-full sm:w-auto"
                      >
                        <span>{elitePackage.ctaText}</span>
                        <ArrowUpLeft className="w-4 h-4" />
                      </Button>
                    </a>
                  </div>
                </div>

                {/* قائمة الميزات الشاملة للباقة */}
                <div className="lg:col-span-7 bg-white/5 p-6 sm:p-8 rounded-xl border border-white/10">
                  <h4 className="text-xs font-semibold uppercase tracking-wider text-neutral-400 mb-4">
                    تشمل باقة النخبة ما يلي:
                  </h4>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-3.5">
                    {elitePackage.features.map((feature, idx) => (
                      <div key={idx} className="flex items-center gap-2.5 text-sm text-neutral-200">
                        <div className="w-4 h-4 rounded-full bg-white/20 flex items-center justify-center shrink-0">
                          <Check className="w-2.5 h-2.5 text-white" />
                        </div>
                        <span>{feature}</span>
                      </div>
                    ))}
                  </div>
                </div>

              </div>
            </Card>
          </div>
        )}

      </div>
    </section>
  );
};