import React from 'react';
import { 
  Code2, 
  Smartphone, 
  ShoppingBag, 
  Layers, 
  Cpu, 
  Users, 
  Handshake, 
  Megaphone, 
  BarChart, 
  ArrowUpLeft,
  CheckCircle2
} from 'lucide-react';
import { additionalServices, contactInfo } from '../../data/agency-info';
import { createWhatsAppLink } from '../../lib/whatsapp';
import { Card } from '../../components/ui/Card';
import { Badge } from '../../components/ui/Badge';
import { Button } from '../../components/ui/Button';

export const ServicesSection: React.FC = () => {
  // مصفوفة الأيقونات المقابلة لكل خدمة
  const digitalIcons = [
    <Code2 key="1" className="w-5 h-5 text-neutral-900" />,
    <ShoppingBag key="2" className="w-5 h-5 text-neutral-900" />,
    <Smartphone key="3" className="w-5 h-5 text-neutral-900" />,
    <Cpu key="4" className="w-5 h-5 text-neutral-900" />,
    <Layers key="5" className="w-5 h-5 text-neutral-900" />
  ];

  const influencerIcons = [
    <Users key="1" className="w-5 h-5 text-neutral-900" />,
    <Handshake key="2" className="w-5 h-5 text-neutral-900" />,
    <Layers key="3" className="w-5 h-5 text-neutral-900" />,
    <Megaphone key="4" className="w-5 h-5 text-neutral-900" />,
    <BarChart key="5" className="w-5 h-5 text-neutral-900" />
  ];

  return (
    <section id="services" className="py-20 lg:py-28 bg-white border-b border-neutral-100">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* رأس القسم */}
        <div className="text-center max-w-2xl mx-auto mb-16 space-y-3">
          <Badge variant="default" className="text-neutral-700">
            خدمات متخصصة
          </Badge>
          <h2 className="text-3xl sm:text-4xl font-extrabold text-neutral-900 tracking-tight">
            الخدمات الإضافية والحلول المتكاملة
          </h2>
          <p className="text-neutral-600 text-sm sm:text-base leading-relaxed">
            حلول برمجية وتسويقية مخصصة لتلبية كافة متطلبات التوسع والتطوير لعلامتك التجارية.
          </p>
        </div>

        {/* شبكة الخدمات الإضافية */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-stretch">
          
          {/* كرت الحلول الرقمية */}
          <Card className="p-8 sm:p-10 flex flex-col justify-between border-neutral-200 bg-neutral-50/50">
            <div>
              <div className="w-12 h-12 rounded-xl bg-neutral-900 text-white flex items-center justify-center mb-6 shadow-sm">
                <Code2 className="w-6 h-6" />
              </div>
              
              <h3 className="text-2xl font-bold text-neutral-900 mb-2">
                {additionalServices[0].title}
              </h3>
              <p className="text-sm text-neutral-500 mb-8 leading-relaxed">
                بناء وتطوير البنية البرمجية والمنصات الرقمية بأحدث التقنيات وأعلى معايير السرعة والأمان.
              </p>

              <ul className="space-y-4 mb-8">
                {additionalServices[0].items.map((item, idx) => (
                  <li key={idx} className="flex items-center gap-3 text-sm font-medium text-neutral-800">
                    <div className="w-8 h-8 rounded-lg bg-white border border-neutral-200 flex items-center justify-center shrink-0">
                      {digitalIcons[idx] || <CheckCircle2 className="w-4 h-4 text-neutral-900" />}
                    </div>
                    <span>{item}</span>
                  </li>
                ))}
              </ul>
            </div>

            <a
              href={createWhatsAppLink(
                contactInfo.defaultWhatsApp,
                'مرحباً NT Media Agency، أود الاستفسار حول خدمات الحلول الرقمية وتطوير الأنظمة والمواقع.'
              )}
              target="_blank"
              rel="noopener noreferrer"
            >
              <Button fullWidth variant="outline" className="gap-2">
                <span>طلب استشارة للحلول الرقمية</span>
                <ArrowUpLeft className="w-4 h-4" />
              </Button>
            </a>
          </Card>

          {/* كرت التسويق عبر المؤثرين */}
          <Card className="p-8 sm:p-10 flex flex-col justify-between border-neutral-200 bg-neutral-50/50">
            <div>
              <div className="w-12 h-12 rounded-xl bg-neutral-900 text-white flex items-center justify-center mb-6 shadow-sm">
                <Users className="w-6 h-6" />
              </div>

              <h3 className="text-2xl font-bold text-neutral-900 mb-2">
                {additionalServices[1].title}
              </h3>
              <p className="text-sm text-neutral-500 mb-8 leading-relaxed">
                إدارة حملات المشاهير والبلوجرز وصناع المحتوى من التخطيط والتفاوض حتى قياس النتائج الميدانية.
              </p>

              <ul className="space-y-4 mb-8">
                {additionalServices[1].items.map((item, idx) => (
                  <li key={idx} className="flex items-center gap-3 text-sm font-medium text-neutral-800">
                    <div className="w-8 h-8 rounded-lg bg-white border border-neutral-200 flex items-center justify-center shrink-0">
                      {influencerIcons[idx] || <CheckCircle2 className="w-4 h-4 text-neutral-900" />}
                    </div>
                    <span>{item}</span>
                  </li>
                ))}
              </ul>
            </div>

            <a
              href={createWhatsAppLink(
                contactInfo.defaultWhatsApp,
                'مرحباً NT Media Agency، أود الاستفسار حول خدمات إدارة حملات المؤثرين والبلوجرز.'
              )}
              target="_blank"
              rel="noopener noreferrer"
            >
              <Button fullWidth variant="outline" className="gap-2">
                <span>طلب حملة تسويق عبر المؤثرين</span>
                <ArrowUpLeft className="w-4 h-4" />
              </Button>
            </a>
          </Card>

        </div>

      </div>
    </section>
  );
};